INSERT INTO feature VALUES('derivation-identity','rewriting','Derivation identity up to reordering',NULL,'implemented','notable',NULL,'Two derivations firing the same cells in independent orders are one, decided by shift equivalence with a causal order and a certified normal form. A family of certificates that share one skeleton folds into one guarded template where it pays, and the template with one row for each member is a reduction of the family: the collapse reads each member''s row from its peak, the inclusion puts the row''s arms in place in the carrier''s peak and join, and the replay refuses a member unlike its instance by name. A row costs one match of the peak against the carrier''s that copies no body, then one lookup of each entry''s body by its address; an instance costs one copy of the carrier''s skeleton, its peak and join built once with every arm in place. A family of families reduces in two steps: the sum of the families'' reductions, then the fold of their templates'' carriers into one template of templates where that pays, whose replay refuses a carrier unlike its instance at its part.','theory-deep-inference','crates/theory-deep-inference/tests/shift.rs crates/theory-deep-inference/tests/causal_web.rs crates/theory-deep-inference/tests/template.rs',NULL,NULL);
